 */import React, { useEffect, useState } from "react";
import Teachernav from "./teachernav";
import axios from "axios";
import { Link } from "react-router-dom";
import toast from "react-hot-toast";

const ViewStudents = () => {
  const [users, setUsers] = useState([]);
  const [classFilter, setClassFilter] = useState(""); // class filter

  // Fetch students (optionally by class)
  const fetchStudents = async (cls) => {
    try {
  const url = cls
      ? `http://localhost:8009/api/users/class1/${cls}` // <-- CORRECT FIX
      : "http://localhost:8009/api/users";
      const response = await axios.get(url);
      setUsers(response.data);
    } catch (error) {
      console.log("❌ Error fetching users:", error);
      toast.error("Failed to fetch students");
    }
  };

  useEffect(() => {
    fetchStudents(classFilter);
  }, [classFilter]);

  // Delete student
  const deleteUser = async (userId) => {
    try {
      const response = await axios.delete(
        `http://localhost:8009/api/delete/user/${userId}`
      );
      setUsers((prev) => prev.filter((user) => user._id !== userId));
      toast.success(response.data.message || "User deleted successfully", {
        position: "top-right",
      });
    } catch (error) {
      console.log("❌ Error deleting user:", error);
      toast.error("Failed to delete user");
    }
  };
  // ViewStudents.js (Add this function)

// Promote students in the currently filtered class
// ViewStudents.js (REPLACE promoteClassHandler with this global version)

// Global Promotion function
const promoteAllClassesHandler = async () => {
    
    // Safety check: Confirm with the user before performing bulk promotion
    const isConfirmed = window.confirm(`⚠️ WARNING: Are you sure you want to promote ALL eligible students (e.g., Class 7 -> 8, Class 8 -> 9, Class 9 -> 10)? This action cannot be undone.`);

    if (!isConfirmed) return;

    try {
        // API call to the global promotion endpoint, sending an empty body or null
        // The backend should be configured to ignore the body and run the global promotion logic.
        const response = await axios.post(
            "http://localhost:8009/api/promote/class",
            {} // Send empty body as the backend now determines classes internally
        );
        
        toast.success(response.data.message, { position: "top-right", duration: 5000 });
        
        // After successful promotion, refetch students based on the current filter
        fetchStudents(classFilter); 
        
    } catch (error) {
        console.log("❌ Error promoting classes:", error);
        const errorMessage = error.response?.data?.message || "Failed to promote classes. Check your server console for details.";
        toast.error(errorMessage);
    }
};
  return (
    <div className="StudentTable" style={{ color: "black", padding: "20px" }}>
      <Teachernav />

      {/* Class Filter */}
      <div style={{ marginBottom: "20px" }}>
        <label>Filter by Class: </label>
        <select
          value={classFilter}
          onChange={(e) => setClassFilter(e.target.value)}
        >
          <option value="">-- All Classes --</option>
          <option value="10" type=
          
          
          "number">10</option>
          <option value="9">9</option>
          <option value="8">8</option>
          <option value="7">7</option>
          <option value="6">6</option>
          <option value="5">5</option>
          <option value="4">4</option><option value="9">9</option>
          <option value="3">3</option>
          <option value="2">2</option>
                    <option value="1">2</option>

        </select>
      </div>

      <table className="table table-bordered">
        <thead>
          <tr>
            <th>S.No.</th>
            <th>Name</th>
            <th>Class</th>
            <th>Roll</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {users.length > 0 ? (
            users.map((user, index) => (
              <tr key={user._id}>
                <td>{index + 1}</td>
                <td>{user.name}</td>
                <td>{user.class1}</td>
                <td>{user.roll}</td>
                <td className="actionButtons">
                  <Link
                    to={`/update/${user._id}`}
                    className="btn btn-info me-2"
                  >
                    <i className="fa-solid fa-pen-to-square">
                      <img src="edit.png" width="40px" height="40px" alt="edit"/>
                    </i>
                  </Link>
                  <button
                    onClick={() => deleteUser(user._id)}
                    className="btn btn-danger"
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="5" style={{ textAlign: "center" }}>
                No users found
              </td>
            </tr>
          )}
        </tbody>
      </table>

<div style={{ marginBottom: "20px", display: 'flex', gap: '15px', alignItems: 'center' }}>
      <label>Filter by Class: </label>
      <select
        value={classFilter}
        onChange={(e) => setClassFilter(e.target.value)}
      >
        <option value="">-- All Classes --</option>
        <option value="10">10</option>
        <option value="9">9</option>
        <option value="8">8</option>
        <option value="7">7</option>
      </select>
      
      {/* ADDED GLOBAL PROMOTION BUTTON */}
      <button
        onClick={promoteAllClassesHandler} // <-- Use the new global handler
        className="btn btn-warning"
        style={{ padding: '5px 15px' }}
      >
        Global Promote All ⬆️
      </button>
    </div>
    
    {/* ... rest of the table and other components */}
      <Link to="/Add_delete" className="btn btn-primary mb-3">
        Add User <i className="fa-solid fa-user-plus"></i>
      </Link>
    </div>
    
  );
};

export default ViewStudents;
